INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.99.0',
  '2026-09-23',
  'Настройки: примерка фона, кадрирование, автосмена и выделение картинок',
  E'Фон в «Оформлении» стал живее. В развёрнутой картинке теперь листаются соседние — стрелками, кнопками по краям или свайпом, а сверху видно размер и вес («2400×1600 · 218 КБ»); если картинка меньше экрана, честно написано, что она будет мылить.\n\n«Примерить» показывает настоящую страницу с этой картинкой на несколько секунд — с размытием, затемнением и точкой фокуса, как оно и будет. Внизу останутся «Оставить» и «Вернуть», а если ничего не нажать, вернётся прежний фон.\n\n«Кадрировать» открывает простой редактор: поворот на 90°, рамка мышью или пальцем и кнопка «Как экран», которая подгоняет рамку под пропорции вашего экрана. Сохраняется копия, оригинал остаётся.\n\n«☑ Выбрать» включает выделение: отметить несколько картинок и разом перенести их в папку или удалить. Над списком видно, сколько картинок и сколько места они занимают, а «сначала тяжёлые» покажет вес на каждой плитке — удобно разбирать.\n\n«Автосмена фона» меняет картинку сама: при каждом открытии или раз в день. Папку можно выбрать отдельно для тёмной и для светлой темы — тогда фон сменится и при переключении темы.\n\nИ мелочь: названия папок теперь спрашиваются своим окном, а не системным prompt, который в Telegram выглядел чужеродно.',
  E'Бэкенд. Миграция 0140 добавила в user_settings колонки bg_auto_mode/bg_auto_dark/bg_auto_light/bg_auto_day. Папка хранится числом: -1 — все картинки, 0 — «без папки», иначе id (внешнего ключа нет: удалённая папка просто перестаёт давать картинки). Новые ручки PUT /settings/background/auto и POST /settings/background/rotate?scheme=dark|light&mode=open|daily|force. Выбор картинки делает сервер (ORDER BY random() с исключением текущей), а решение «пора ли» — клиент, кроме режима daily: там сверка идёт с current_date сервера, иначе телефон в другом часовом поясе менял бы фон второй раз. Ответ о фоне собирается общим backgroundState() и теперь содержит auto и size каждой картинки (os.Stat, колонки в базе нет — файл на диске не соврёт); размер отдаёт и /appearance/gallery.\n\nФронтенд. BackgroundPicker разобран на bg/ImageTile.vue, bg/ImageViewer.vue, bg/CropEditor.vue и bg/AutoBg.vue. Просмотрщик листает список той группы, из которой открыт (свои по папкам, галерея по категориям), Esc/←/→ и свайп. Примерка зовёт applyBackground() напрямую, ничего не сохраняя, и по таймеру возвращает прежнюю картинку; на это время просмотрщик скрывается, иначе примерять нечего. Кадрирование рисует картинку, затемнение вне рамки и уголки в одном canvas — отдельный слой-оверлей пришлось бы сводить по координатам; раскладка считается в nextTick, а не в requestAnimationFrame (в скрытой вкладке rAF не приходит вовсе, и холст оставался 300×150), плюс ResizeObserver; вывод не больше 3000 px по длинной стороне и webp 0.92 с откатом на jpeg. Автосмена запускается из main.ts (startBackgroundAuto после loadBackground) и вешает watch на activeTheme.kind — при разных папках тема переключает и фон. window.prompt заменён на shared/ask.ts + components/AskModal.vue (промис + одно окно в App.vue, как тосты); заодно переведены две ручки в админской галерее.\n\nПроверено в браузере на локальном сервере: листание и сведения о картинке, примерка с возвратом по таймеру, кадрирование с «Как экран» (получилось 1440×731 при экране 1,97), выделение с переносом в папку и удалением, автосмена в режимах daily (повторный заход не меняет) и open (меняет), смена картинки при переключении темы на светлую, создание и переименование папки новым окном ввода.'
);
-- +goose StatementEnd

